function dayKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function previousDay(key){const d=new Date(key+'T12:00:00');d.setDate(d.getDate()-1);return dayKey(d)}
function validNonLearningCompat147(s){
 if(!s||s.version!==1||!s.completed||!s.events||!s.words||Object.keys(s.events).length>10000||Object.keys(s.completed).length>50000||Object.keys(s.words).length>500000)throw Error(Arabic169.primary("صيغة ملف التقدم مش صحيحة","ui"));
 const out=empty();out.formative=sanitizeFormative(s.formative);
 for(const [k,v] of Object.entries(s.completed)){if(LESSON_LEDGER_SHAPE.test(k)&&Number.isFinite(v?.at)&&Number.isFinite(v.score))out.completed[k]={at:v.at,score:Math.max(0,Math.min(100,v.score))}}
 for(const [k,v] of Object.entries(s.events)){if(/^[\w:-]{1,90}$/.test(k)&&/^\d{4}-\d{2}-\d{2}$/.test(v.day)&&[5,10,20].includes(v.xp))out.events[k]={day:v.day,xp:v.xp}}
 for(const [k,v] of Object.entries(s.words)){if(WORD_LEDGER_SHAPE.test(k)&&Number.isFinite(v?.at)&&Number.isFinite(v.due)&&Number.isFinite(v.stage))out.words[k]={at:v.at,due:v.due,stage:Math.max(0,Math.min(4,v.stage))}}
 out.placement=s.placement&&Number.isFinite(s.placement.at)&&Number.isInteger(s.placement.index)?{at:s.placement.at,index:Math.max(0,Math.min(MAIN_LESSONS.length-1,s.placement.index)),kind:s.placement.kind==='zero'?'zero':'screen'}:null;out.activity={};for(const [day,a]of Object.entries(s.activity||{}).slice(-90)){if(/^\d{4}-\d{2}-\d{2}$/.test(day)&&Number.isFinite(a?.cards))out.activity[day]={cards:Math.max(0,Math.min(100,a.cards)),stories:Math.max(0,Math.min(50,Number(a.stories)||0))}}
 out.settings={goal:[10,20,40].includes(s.settings?.goal)?s.settings.goal:20,speed:[.65,.85,1].includes(s.settings?.speed)?s.settings.speed:.85,sfx:s.settings?.sfx!==false,sfxStyle:Object.hasOwn(SFX_STYLES,s.settings?.sfxStyle)?s.settings.sfxStyle:"classic"};
 return out;
}
function validData(s){
 const out=validNonLearningCompat147(s),c=globalThis.LEARNING_PROGRESS_CONTRACT,now=Date.now();out.completed={};
 for(const [id,v] of Object.entries(s.completed))if(c.LESSON_ID_SHAPE.test(id)&&Number.isFinite(v?.at)&&Number.isFinite(v.score))out.completed[id]={at:Math.min(v.at,now+300000),score:Math.max(0,Math.min(100,v.score)),...(c.shortPart(id)&&v.inherited143===true?{inherited143:true}:{})};
 out.events=c.normalizeLearningEvents(s.events);out.short143=c.sanitizeShortLedger(s.short143,{now});return out;
}
function mergeNonLearningCompat147(a,b){const out=validData(a);b=validData(b);for(const key of ['completed','words'])for(const [k,v]of Object.entries(b[key]))if(!out[key][k]||v.at>out[key][k].at)out[key][k]=v;out.events={...out.events,...b.events};out.formative=mergeFormative(out.formative,b.formative);out.placement=(b.placement?.at||0)>(out.placement?.at||0)?b.placement:out.placement;for(const [day,a]of Object.entries(b.activity||{}))out.activity[day]={cards:Math.max(out.activity[day]?.cards||0,a.cards),stories:Math.max(out.activity[day]?.stories||0,a.stories||0)};return out}
function mergeLearning(a,b){const out=mergeNonLearningCompat147(a,b),aa=validData(a),bb=validData(b),c=globalThis.LEARNING_PROGRESS_CONTRACT;out.completed=c.mergeCompletions(aa.completed,bb.completed);out.events=c.mergeLearningEvents(aa.events,bb.events);out.short143=c.mergeShortLedger(aa.short143,bb.short143);return out}
function load(){try{const raw=localStorage.getItem(STORE);if(raw){const s=JSON.parse(raw);state={...validData(s),session:s.session||null,sessions:s.sessions||{},activeCourseId:s.activeCourseId||'main',account:s.account||null}}}catch(e){storageOK=false}}
function save(sync=true){state.events=globalThis.LEARNING_PROGRESS_CONTRACT.normalizeLearningEvents(state.events);state.sessions=state.sessions||{};state.sessions[activeCourseId]=state.session;state.activeCourseId=activeCourseId;try{localStorage.setItem(STORE,JSON.stringify(state));storageOK=true}catch(e){storageOK=false}if(sync&&state.account){clearTimeout(syncTimer);syncTimer=setTimeout(syncAccount,1200)}}
function xp(){return Object.values(state.events).reduce((n,e)=>n+e.xp,0)}
function todayXP(){return Object.values(state.events).filter(e=>e.day===dayKey()).reduce((n,e)=>n+e.xp,0)}
function streak(){const days=new Set(Object.values(state.events).filter(e=>e.xp>0).map(e=>e.day));let key=days.has(dayKey())?dayKey():previousDay(dayKey()),n=0;while(days.has(key)){n++;key=previousDay(key)}return n}
function dueWords(){return WORDS.filter(w=>state.words[w.id]&&state.words[w.id].due<=Date.now())}
