function progress(){if(activeJob())return jobProgress();const n=LESSONS.filter(l=>state.completed[l.id]).length,days=new Set(Object.values(state.events).map(e=>e.day));const badges=[['✦',Arabic169.primary("أول خطوة","ui"),n>=1],['☕',Arabic169.primary("طلبك بالإسباني","ui"),!!state.completed.u3l3],[FLAME,Arabic169.primary("٣ أيام ورا بعض","ui"),streak()>=3],['★',Arabic169.primary("نهاية البداية","ui"),INTRO_LESSON_IDS.every(id=>state.completed[id])]];const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-(6-i));return d});return layout(Arabic169.template("30067f61515278b2")`<div class="reading"><div class="eyebrow">إنجاز حقيقي، من غير مقارنة بحد</div><h1>بص إنت وصلت لفين.</h1><div class="grid2"><div class="metric"><b>${ArabicCount169.label(xp(),"learningStep")}</b><span>خطوات تعلّمك من الدروس والمراجعة</span></div><div class="metric"><b>${ArabicCount169.format(streak())}</b><span>أيامك المتتالية</span></div></div><section class="card" style="margin-top:18px"><div class="between"><h3>هدفك اليومي</h3><span class="chip"><bdi dir="ltr">${ArabicCount169.format(todayXP())} / ${ArabicCount169.format(state.settings.goal)}</bdi></span></div>${bar(todayXP()/state.settings.goal*100)}<div class="week">${week.map(d=>`<div class="day ${days.has(dayKey(d))?'on':''}"><b>${days.has(dayKey(d))?'✓':'·'}</b>${d.toLocaleDateString('ar-EG',{weekday:'short'})}</div>`).join('')}</div><p class="small" style="margin-top:12px">الأيام المتتالية بتتحسب على توقيت جهازك. يوم من غير خطوات تعلّم بيقطع التتابع، مش بيمسح تقدمك.</p></section><section class="card"><div class="between"><h3>المسار التمهيدي داخل A1</h3><bdi>${ArabicCount169.format(n)}/${ArabicCount169.format(LESSONS.length)}</bdi></div>${bar(n/LESSONS.length*100)}<p style="margin-top:10px">${ArabicCount169.selected(WORDS.filter(w=>state.words[w.id]).length,"expression",WORDS.filter(w=>state.words[w.id]).length)} تعبير في قاموسك. إكمال المسار ده مش معناه إكمال مستوى A1 كله.</p></section><h2>شاراتك</h2><div class="grid2">${badges.map(([ico,title,on])=>`<div class="badge ${on?'':'missing'}"><span>${ico}</span><strong>${title}</strong><small>${on?Arabic169.primary("حققتها","ui"):Arabic169.primary("لسه قدّامك","ui")}</small></div>`).join('')}</div><section class="card" style="margin-top:20px"><h3>شهادة إتمام البداية</h3><p>تفتح بعد أول ١٨ درس في المسار التمهيدي الأصلي. شهادة تشجيعية لإتمام المسار التمهيدي داخل A1، مش شهادة لغة معتمدة.</p>${INTRO_LESSON_IDS.every(id=>state.completed[id])?Arabic169.primary("<a href=\"#certificate\" class=\"btn secondary\">افتح الشهادة</a>","ui"):Arabic169.template("e9c225c25f2a3abf")`<span class="chip">باقي ${ArabicCount169.selected(INTRO_LESSON_IDS.filter(id=>!state.completed[id]).length,"lesson",INTRO_LESSON_IDS.filter(id=>!state.completed[id]).length)} درس</span>`}</section><div class="notice">لو بتستخدم وضع الزائر، تقدمك محفوظ على المتصفح ده بس. الحساب الاختياري بيزامن التقدم لما تتصل بالإنترنت.</div></div>`)}
