function lessonDeck(l){if(l?.short143&&typeof shortDeck143==='function')return shortDeck143(l);const all=exercises(l);all.splice(l.words.length,0,{type:'teachdialog',dialog:l.dialog});const extra=skillQuestions(l);all.splice(l.words.length+1,0,...extra.filter(q=>q.type==='alphabet'));all.push(...extra.filter(q=>q.type!=='alphabet'));return all}
function gradedDeck(l){return lessonDeck(l).filter(q=>!['teach','teachdialog','warmup143','alphabet','skillread','skilllisten','skillwrite'].includes(q.type))}
function startLesson(id){view.q=null;view.result=null;const l=lessonById(id);if(!l)return;if(!isUnlocked(l))return toast(Arabic169.primary("كمّل الدرس السابق الأول.","ui"));if(!state.session||state.session.lessonId!==id)state.session={lessonId:id,at:0,correct:0,attempts:0,wordResults:{},curriculum:l.short143?143:107};save(false);location.hash='lesson/'+id;render()}
