async function syncAccount(){if(!state.account)return;if(!navigator.onLine){syncMessage=Arabic169.primary("مفيش نت. تقدمك محفوظ على الجهاز وهيتزامن أول ما الاتصال يرجع.","ui");return}if(syncBusy){syncAgain=true;return}syncBusy=true;const accountId=state.account.id;try{const result=await api('sync',{progress:validData(state)});if(state.account?.id===accountId){const merged=mergeLearning(state,result.progress);state.completed=merged.completed;state.words=merged.words;state.events=merged.events;state.placement=merged.placement;state.activity=merged.activity;state.formative=merged.formative;state.short143=merged.short143;if(typeof accountScheduleProjection147==='function'&&accountScheduleProjection147(result.progress))syncAgain=true;save(false);syncMessage=Arabic169.primary("آخر مزامنة: ","ui")+new Date().toLocaleTimeString('ar-EG');if(['settings','home','path','progress','review','courses'].includes(view.page))render();}}catch(e){syncMessage=e.message;if(e.status===401){needsReauth=true;if(view.page==='settings')render()}if(view.page==='settings')authStatus(syncMessage)}finally{syncBusy=false;if(syncAgain){syncAgain=false;syncAccount()}}}
