function unitPath(u,ui){return Arabic169.template("2e80682e3bd376c5")`<section class="unit" data-path-unit="${ui}"><header class="unithead">${unitContextImage(ui,'unit-head-art')}<div class="row"><span class="uniticon">${u.icon}</span><div><div class="eyebrow">${activeJob()?courseTitle():u.level||'A1'} • الوحدة ${ArabicCount169.format(filteredCourseUnits(LESSONS.find(l=>!state.completed[l.id])).findIndex(([u,i])=>i===ui)+1)} • ${u.tag==='مواقف وتدريب'?u.tag:arabicTitle171(u.tag,'ui')}</div><h3 style="margin:0">${esc(arabicTitle171(u.title,Arabic169.domainForLesson(u)))}</h3></div></div><p>${esc(arabicText169(u.desc,Arabic169.domainForLesson(u)))}</p>${offlineUnitControl(ui)}</header><div class="path">${LESSONS.filter(l=>l.unit===ui).map(l=>{const done=state.completed[l.id],unlocked=isUnlocked(l);return `<button class="lessonrow" data-action="start" data-id="${l.id}" ${!unlocked?'disabled':''}><span class="node ${done?'done':unlocked?'current':''}">${done?'✓':unlocked?'▶':'<svg width="20" height="24" viewBox="0 0 24 28" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="4" y="12" width="16" height="13" rx="3"/><path d="M7 12V8a5 5 0 0 1 10 0v4M12 17v4"/></svg>'}</span><span><strong>${esc(arabicTitle171(l.title,Arabic169.domainForLesson(l)))}</strong><small>${done?Arabic169.primary("مكتمل • تقدر تراجع","ui"):unlocked?Arabic169.template("221b1180132969c7")`${ArabicCount169.selected(l.words.length,"expression",l.words.length)} تعبيرات • ${l.short143?ArabicCount169.selected(lessonDeck(l).length,'step',lessonDeck(l).length+' خطوة أساسية، ومراجعة الغلط زيادة','basic')+(Arabic169.getMode()==='egyptian'?'':'، إضافةً إلى مراجعة الأخطاء'):Arabic169.primary("تدريب متنوّع","ui")}`:Arabic169.primary("كمّل الدرس السابق الأول","ui")}</small></span></button>`}).join('')}</div>${formativeUnitControl(ui)}</section>`}

/* Bounded course path and opt-in per-unit audio. Stable progress IDs stay unchanged. */
const PATH_PAGE_SIZE=1,MEDIA_CACHE='yalla-espanol-media-v1';
const unitDownloads=new Set();
function publishedLevels(){return [...new Set(UNITS.map(u=>u.level||'A1'))]}
function activeCourseLevel(next){const levels=publishedLevels();return levels.includes(view.courseLevel)?view.courseLevel:(next?.level||'A1')}
function filteredCourseUnits(next){const level=activeCourseLevel(next);return UNITS.map((u,ui)=>[u,ui]).filter(([u])=>(u.level||'A1')===level)}
function pathPageIndex(next){const units=filteredCourseUnits(next),nextAt=Math.max(0,units.findIndex(([u,ui])=>ui===next?.unit)),requested=Number.isInteger(view.pathPage)?view.pathPage:Math.floor(nextAt/PATH_PAGE_SIZE);return Math.max(0,Math.min(Math.max(0,Math.ceil(units.length/PATH_PAGE_SIZE)-1),requested))}
function pathUnits(next){const start=pathPageIndex(next)*PATH_PAGE_SIZE;return filteredCourseUnits(next).slice(start,start+PATH_PAGE_SIZE)}
function unitNavigator(next){const level=activeCourseLevel(next),units=filteredCourseUnits(next),page=pathPageIndex(next),start=page*PATH_PAGE_SIZE;return Arabic169.template("11ddef2e7d7e6862")`<section class="card" id="path-navigation"><label for="course-level">المستوى المتاح</label><select id="course-level" style="width:100%;margin:12px 0">${publishedLevels().map(id=>`<option value="${id}" ${id===level?'selected':''}>${activeJob()?courseTitle():id}</option>`).join('')}</select><label for="path-unit">اختار وحدة في المسار</label><select id="path-unit" style="width:100%;margin:12px 0">${units.map(([u,ui],i)=>`<option value="${ui}" ${i===start?'selected':''}>${ArabicCount169.format(i+1)}. ${esc(arabicTitle171(u.title,Arabic169.domainForLesson(u)))}</option>`).join('')}</select><div class="rowgap"><button class="btn secondary" data-action="path-page" data-page="${page-1}" ${page===0?'disabled':''}>الوحدات السابقة</button><button class="btn secondary" data-action="path-page" data-page="${page+1}" ${start+PATH_PAGE_SIZE>=units.length?'disabled':''}>الوحدات التالية</button></div><p class="small" style="margin-top:12px" role="status">${activeJob()?courseTitle():level} • الوحدات ${ArabicCount169.format(start+1)}–${ArabicCount169.format(Math.min(start+PATH_PAGE_SIZE,units.length))} من ${ArabicCount169.format(units.length)}. عرض الوحدات مش بيفتح دروس قبل وقتها.</p></section>`}
function unitAudioFiles(ui){const result=new Set(),add=(text,speaker)=>{const file=(typeof AUDIO_CAST_MAP!=='undefined'&&AUDIO_CAST_MAP[speaker+':'+text])||(typeof AUDIO_MAP!=='undefined'&&AUDIO_MAP[text]);if(file)result.add(file)};for(const l of LESSONS.filter(l=>l.unit===ui)){for(const w of l.words)add(w.es,w.speaker||'paco');l.dialog.forEach((text,i)=>{if(i<2)add(text,l.dialogSpeakers?.[i]||(i?'paco':'luna'))});for(const r of ASSESSMENT_OVERRIDES[l.id]?.replyAlternatives||[])add(r.es,l.dialogSpeakers?.[1]||'paco');for(const turn of l.skillPractice?.turns||[])add(turn.es,turn.speaker);if(l.id==='u34l1')for(const letter of ALPHABET_AUDIO)add(letter.text,letter.speaker)}if(!activeJob()){const id=MAIN_UNITS[ui].id||'u'+(ui+1);for(const t of FORMATIVE_BANK.tests.filter(t=>t.unitIds.includes(id)))for(const q of t.items)if(q.audio)add(q.audio.textEs,q.audio.speaker)}return [...result]}
function offlineUnitControl(ui){return Arabic169.template("7a3316a101b95ab3")`<div style="margin-top:14px"><button class="btn secondary" data-action="download-unit" data-unit="${ui}" ${unitDownloads.has(ui)?'disabled':''}>${unitDownloads.has(ui)?Arabic169.primary("بننزّل الصوت…","ui"):Arabic169.primary("نزّل صوت الوحدة عشان تسمعه من غير نت","ui")}</button><p class="small" role="status" data-offline-unit="${ui}" style="margin-top:8px">الصوت بيتنزّل عند الطلب، مش المكتبة كلها.</p></div>`}
function setOfflineStatus(ui,text,ready=false){const el=document.querySelector(`[data-offline-unit="${ui}"]`);if(el)el.textContent=arabicApiText169(text);document.querySelectorAll(`[data-action="download-unit"][data-unit="${ui}"]`).forEach(b=>{b.disabled=unitDownloads.has(ui);b.textContent=unitDownloads.has(ui)?Arabic169.primary("بننزّل الصوت…","ui"):ready?Arabic169.primary("راجع تنزيل صوت الوحدة","ui"):Arabic169.primary("نزّل صوت الوحدة عشان تسمعه من غير نت","ui")})}
async function refreshOfflineBadges(){if(!('caches'in window))return;const cache=await caches.open(MEDIA_CACHE);for(const el of document.querySelectorAll('[data-offline-unit]')){const ui=Number(el.dataset.offlineUnit);if(unitDownloads.has(ui))continue;const paths=unitAudioFiles(ui),hits=await Promise.all(paths.map(p=>cache.match(p)));const n=hits.filter(Boolean).length;setOfflineStatus(ui,n===paths.length&&n?Arabic169.template("84951efc295cf68a")`صوت الوحدة محفوظ: ${ArabicCount169.selected(n,"file",n)} ملف. ممكن المتصفح يمسحه لو المساحة قليلة.`:n?Arabic169.template("15723d2d197c4168")`${ArabicCount169.format(n)} من ${ArabicCount169.selected(paths.length,"file",paths.length)} ملف محفوظ. اضغط التنزيل لتكملة الباقي.`:Arabic169.primary("الصوت بيتنزّل عند الطلب، مش المكتبة كلها.","ui"),n===paths.length&&n>0)}}
async function downloadUnitAudio(ui){if(!Number.isInteger(ui)||!UNITS[ui]||unitDownloads.has(ui))return;if(!('caches'in window))return toast(Arabic169.primary("حفظ الصوت للتشغيل من غير نت محتاج متصفح بيدعم حفظ الملفات على الجهاز.","ui"));unitDownloads.add(ui);let finished=0;const paths=unitAudioFiles(ui);setOfflineStatus(ui,Arabic169.template("fa760b1c401c7f08")`جاري تنزيل ${ArabicCount169.selected(paths.length,"file",paths.length)} ملف…`);try{const cache=await caches.open(MEDIA_CACHE);let next=0;async function worker(){while(next<paths.length){const path=paths[next++];if(!await cache.match(path)){const response=await fetch(path,{cache:'reload'});if(!response.ok||response.status!==200)throw Error('download');await cache.put(path,response)}finished++;setOfflineStatus(ui,Arabic169.template("fdab183e6a07ebf0")`اتحفظ ${ArabicCount169.format(finished)} من ${ArabicCount169.selected(paths.length,"file",paths.length)} ملف…`)}}const outcomes=await Promise.allSettled(Array.from({length:Math.min(3,paths.length)},worker));if(outcomes.some(r=>r.status==='rejected'))throw Error('partial');toast(Arabic169.primary("صوت الوحدة اتحفظ على الجهاز. جرّبه قبل ما تفصل الإنترنت.","ui"))}catch(e){toast(Arabic169.primary("التنزيل ما كملش. الجزء اللي اتحفظ موجود، جرّب تاني وإنت متصل.","ui"))}finally{unitDownloads.delete(ui);await refreshOfflineBadges()}}
async function clearDownloadedAudio(){if(!('caches'in window))return toast(Arabic169.primary("حفظ الصوت مش متاح في المتصفح ده.","ui"));if(unitDownloads.size)return toast(Arabic169.primary("استنى تنزيل الوحدة يخلص الأول.","ui"));await caches.delete(MEDIA_CACHE);toast(Arabic169.primary("التسجيلات المحفوظة اتمسحت من الجهاز ده بس. تقدمك زي ما هو.","ui"));await refreshOfflineBadges()}
